memberdef.definition:
using themis::acceleration::ANNDistanceFn =  int (*)(
    const float* d_queries,   
    const float* d_vectors,   
    float*       d_distances, 
    int          numQueries,
    int          numVectors,
    int          dim,
    void*        opaque_stream
)

using themis::acceleration::ANNTopKFn =  int (*)(
    const float* d_distances,    
    uint32_t*    d_topk_indices, 
    float*       d_topk_dists,   
    int          numQueries,
    int          numVectors,
    int          topK,
    void*        opaque_stream
)

using themis::acceleration::GeoDistanceFn =  int (*)(
    const double*      d_latitudes1,  
    const double*      d_longitudes1, 
    const double*      d_latitudes2,  
    const double*      d_longitudes2, 
    float*             d_distances,   
    int                count,
    GeoDistanceFormula formula,
    void*              opaque_stream
)

using themis::acceleration::GeoContainmentFn =  int (*)(
    const double* d_point_lats,      
    const double* d_point_lons,      
    int           numPoints,
    const double* d_polygon_coords,  
    int           numPolygonVertices,
    uint8_t*      d_results,         
    void*         opaque_stream
)

using themis::acceleration::MatrixKernelFn =  int (*)(
    const MatrixKernelParams& params,
    void* opaque_stream
)

